// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts) public {
        // admissible: divisible-by-15 block, strictly increasing timestamp
        blockNum = bound(blockNum, 15, type(uint256).max - 1);
        vm.assume(blockNum % 15 == 0);
        ts = bound(ts, 1, type(uint256).max - 1);
        vm.roll(blockNum);
        vm.warp(ts);

        address actor = address(0xA11CE);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Rule: on a block number divisible by 15, C transfers out its whole balance.
        assertTrue((blockNum % 15 != 0) || (address(c).balance == 0), "balance must be drained on payout block");
    }
}
